  position: fixed;
  z-index: var(--ant-z-index-popup-base);
  inset-inline-end: var(--ant-margin-lg);
  bottom: var(--ant-margin-xxl);
  box-shadow: var(--ant-box-shadow-secondary);
  /* v6 `.ant-float-btn { padding; gap }` is meant for antd's inline-flex Button root. ng-zorro's host
     is a block around `.ant-float-btn-inner`, which fills it, so both are reset. */
  padding: 0;
  gap: 0;
