  margin-inline-end: var(--ant-line-width);
}
.ant-float-btn-square .ant-badge > .ant-badge-dot {
  margin-top: calc(var(--ant-line-width) + var(--ant-border-radius) * 0.29289321881345254);
  margin-inline-end: calc(var(--ant-line-width) + var(--ant-border-radius) * 0.29289321881345254);
}
/* The progress ring is a real border on the inner button, so the wrapper already sits inside it. */
.ant-float-btn-progress.ant-float-btn-circle .ant-badge > .ant-badge-count,
.ant-float-btn-progress.ant-float-btn-circle .ant-badge > .ant-badge-dot {
  margin-top: calc(var(--ant-control-height) / 2 * 0.29289321881345254);
  margin-inline-end: calc(var(--ant-control-height) / 2 * 0.29289321881345254);
}
.ant-float-btn-progress.ant-float-btn-square .ant-badge > .ant-badge-count {
